package thing_test

import (
	"testing"

	"thing"
)

// Run answers for what it reads. Slot: the tests of its own logic.
func TestRunAnswersForWhatItReads(t *testing.T) {
	out, err := thing.Run(thing.In{Words: []string{"a", "b"}})
	if err != nil {
		t.Fatal(err)
	}
	if out.Count != 2 {
		t.Fatalf("Run counted %d words, want 2", out.Count)
	}
}

